-- Eterno Pacto Kids · más formatos de archivo (Word, PowerPoint, Excel, audio, video) y hasta 50 MB
update storage.buckets set file_size_limit = 52428800, allowed_mime_types = array['application/pdf','image/png','image/jpeg','image/gif','image/webp','video/mp4','video/webm','text/plain','text/csv','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','audio/mpeg','audio/mp4','video/quicktime'] where id = 'archivos';
select 'Listo: formatos ampliados' as resultado, file_size_limit, array_length(allowed_mime_types,1) as formatos from storage.buckets where id = 'archivos';
